package com.guardianxr.ar;
import android.app.*;import android.os.*;import android.graphics.Color;import android.content.*;import android.view.*;import android.widget.*;
public class VerifyActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(30,50,30,30);l.setBackgroundColor(0xff07101c);TextView h=new TextView(this);h.setText("QR CERTIFICATE VERIFICATION");h.setTextColor(Color.WHITE);h.setTextSize(22);l.addView(h);EditText e=new EditText(this);e.setHint("Enter GXR certificate ID");e.setTextColor(Color.WHITE);e.setHintTextColor(0xff9eacc2);l.addView(e);TextView out=new TextView(this);out.setTextColor(Color.WHITE);out.setTextSize(18);Button v=new Button(this);v.setText("Verify offline");v.setOnClickListener(x->{String id=e.getText().toString().trim();String data=getSharedPreferences("guardianxr",MODE_PRIVATE).getString("cert_"+id,null);out.setText(data==null?"NOT VERIFIED":"VERIFIED ✓\n"+data);});l.addView(v);l.addView(out);setContentView(l);}}
